"""Loads data/pin_db.yaml (generated by gen_pin_db.py) into Pin records."""
from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path

import yaml

from .types import PinType

DEFAULT_PIN_DB_PATH = Path(__file__).resolve().parent / "data" / "pin_db.yaml"


@dataclass(frozen=True)
class Pin:
    name: str
    block: str
    direction: str  # "in" | "out"
    pad_digital_sheet: int | None
    pad_io_pins_dima: int | None
    fmc_la: str | None
    allowed_types: tuple[PinType, ...]
    limits: dict = field(default_factory=dict)
    idle_level: str | None = None
    polarity: str | None = None
    notes: str = ""


def load_pin_db(path: Path | None = None) -> dict[str, Pin]:
    path = path or DEFAULT_PIN_DB_PATH
    with open(path) as f:
        doc = yaml.safe_load(f)
    pins: dict[str, Pin] = {}
    for raw in doc["pins"]:
        pins[raw["name"]] = Pin(
            name=raw["name"],
            block=raw["block"],
            direction=raw["direction"],
            pad_digital_sheet=raw["pad_digital_sheet"],
            pad_io_pins_dima=raw["pad_io_pins_dima"],
            fmc_la=raw["fmc_la"],
            allowed_types=tuple(PinType(t) for t in raw["allowed_types"]),
            limits=raw.get("limits") or {},
            idle_level=raw.get("idle_level"),
            polarity=raw.get("polarity"),
            notes=raw.get("notes", ""),
        )
    return pins


def blocks(pin_db: dict[str, Pin]) -> dict[str, list[str]]:
    """block name -> list of pin names, in pin_db order."""
    out: dict[str, list[str]] = {}
    for pin in pin_db.values():
        out.setdefault(pin.block, []).append(pin.name)
    return out


def input_blocks(pin_db: dict[str, Pin]) -> dict[str, list[str]]:
    """block name -> list of *input* pin names only, in pin_db order. The Phase 2
    wizard walks these (generic_controller_prompt.md §3 Phase 2: "each input pin")."""
    out: dict[str, list[str]] = {}
    for pin in pin_db.values():
        if pin.direction == "in":
            out.setdefault(pin.block, []).append(pin.name)
    return out
